int attach_usb_serial(struct usb_serial *serial) {
    if (!serial || serial->num_ports < 2 || !serial->port[0] || !serial->port[1]) {
        return -ENODEV;
    }

    if (!serial->port[1]->bulk_out_endpointAddr) {
        return -ENODEV;
    }

    serial->port[0]->bulk_out_endpointAddr = serial->port[1]->bulk_out_endpointAddr;

    serial->port[0]->write_urb->pipe = usb_sndbulkpipe(serial->dev, serial->port[0]->bulk_out_endpointAddr);

    return 0;
}
